import java.io.*;
import java.util.Arrays;

/**
 * Created by dalt on 2018/3/14.
 */
public class CF939F_Variant4 {
    public static final int INF = (int) 1e8;
    public static BufferedReader br;
    public static PrintStream ps;

    public static void main(String[] args) throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        ps = System.out;

        run();

        ps.flush();
    }

    public static void run() throws IOException {
        String[] line = br.readLine().split(" ");
        int n = Integer.parseInt(line[0]);
        int k = Integer.parseInt(line[1]);

        int[][] intervals = new int[k + 2][2];
        for (int i = 1; i <= k; i++) {
            String[] parts = br.readLine().split(" ");
            intervals[i][0] = Integer.parseInt(parts[0]);
            intervals[i][1] = Integer.parseInt(parts[1]);
        }
        intervals[k + 1][0] = 2 * n;
        intervals[k + 1][1] = 2 * n;

        k++;

        Node[] dp = new Node[2];
        dp[0] = Node.build(0, n);
        dp[1] = Node.build(0, n);

        int[] buffer = new int[n + 1];

        for (int i = 1; i <= k; i++) {
            Node currentNode = dp[i & 1];
            Node prevNode = dp[(i - 1) & 1];

            int[] interval = intervals[i];
            int intervalSize = interval[1] - interval[0];
            int middleSize = interval[0] - intervals[i - 1][1];

            Node.toArray(0, n, buffer, prevNode);
            System.arraycopy(buffer, 0, buffer, Math.min(buffer.length, intervalSize + middleSize), Math.max(0, n + 1 - (intervalSize + middleSize)));
            Arrays.fill(buffer, 0, Math.min(buffer.length, intervalSize + middleSize), INF);

            int minX = interval[1] - middleSize - intervalSize;
            int maxX = interval[1] - middleSize;
            for (int j = 0; j <= n; j++) {
                int needTime = Node.query(minX - j, maxX - j, 0, n, prevNode);
                buffer[j] = Math.min(buffer[j], needTime + 1);
            }

            for (int j = 0; j <= n; j++) {
                int needTime = Node.query(j - middleSize - intervalSize, j - middleSize, 0, n, prevNode);
                buffer[j] = Math.min(buffer[j], needTime + 2);
            }

            Node.fromArray(0, n, buffer, currentNode);
        }

        int res = Node.query(n, n, 0, n, dp[k & 1]);
        if (res < INF) {
            ps.println("Full");
            ps.println(res);
        } else {
            ps.println("Hungry");
        }
    }

    static class Node {
        Node left, right;
        int min;
        boolean dirty;
        int val;

        public static void setRange(int f, int t, int l, int r, int v, Node node) {
            if (f > r || t < l) return;
            if (f <= l && t >= r) {
                node.setVal(v);
                return;
            }
            node.pushDown();
            int m = (l + r) >> 1;
            setRange(f, t, l, m, v, node.left);
            setRange(f, t, m + 1, r, v, node.right);
            node.update();
        }

        public static Node create(int l, int r) {
            Node node = new Node();
            if (l != r) {
                int m = (l + r) >> 1;
                node.left = create(l, m);
                node.right = create(m + 1, r);
            }
            node.min = INF;
            return node;
        }

        public static int queryRange(int f, int t, int l, int r, Node node) {
            if (f > r || t < l) return INF;
            if (f <= l && r <= t) return node.min;
            node.pushDown();
            int m = (l + r) >> 1;
            return Math.min(queryRange(f, t, l, m, node.left), queryRange(f, t, m + 1, r, node.right));
        }

        public static void fillFromArray(int l, int r, int[] data, Node node) {
            if (l == r) {
                node.min = data[l];
                return;
            }
            int m = (l + r) >> 1;
            fillFromArray(l, m, data, node.left);
            fillFromArray(m + 1, r, data, node.right);
            node.update();
        }

        public static void fillToArray(int l, int r, int[] data, Node node) {
            if (l == r) {
                data[l] = node.min;
                return;
            }
            node.pushDown();
            int m = (l + r) >> 1;
            fillToArray(l, m, data, node.left);
            fillToArray(m + 1, r, data, node.right);
        }

        public void update() {
            this.min = Math.min(left.min, right.min);
        }

        public void setVal(int v) {
            this.min = v;
            this.val = v;
            this.dirty = true;
        }

        public void pushDown() {
            if (dirty) {
                left.setVal(val);
                right.setVal(val);
                dirty = false;
            }
        }
    }
}
